-- Bo du lieu kiem thu rieng gom 6 ho so. Tep kem: sql/du-lieu-mau/files.
-- Tao schema trong database kiem thu truoc khi chay tep nay.
SET XACT_ABORT ON;
IF DB_NAME() NOT LIKE N'CongMotCua[_]KiemThu%' THROW 51021,N'Chon database kiem thu co tien to CongMotCua_KiemThu.',1;
IF EXISTS(SELECT 1 FROM dbo.BoPhan) OR EXISTS(SELECT 1 FROM dbo.NguoiDung) OR EXISTS(SELECT 1 FROM dbo.ThuTuc) OR EXISTS(SELECT 1 FROM dbo.HoSo) THROW 51020,N'Database da co du lieu; khong chen de ghi de du lieu cu.',1;
BEGIN TRANSACTION;
-- BoPhan: 2 dong
-- NguoiDung: 5 dong
-- ThuTuc: 3 dong
-- ThanhPhanYeuCau: 6 dong
-- HoSo: 6 dong
-- PhanCongXuLy: 3 dong
-- YeuCauBoSung: 0 dong
-- NoiDungBoSung: 0 dong
-- LanBoSung: 0 dong
-- TaiLieuHoSo: 12 dong
-- KiemTraThanhPhan: 8 dong
-- KetQuaHoSo: 2 dong
-- LichSuXuLy: 16 dong
COMMIT TRANSACTION;
GO
